import{z as p,x as s,o as t,c as B,q as r,j as o,D as E,d as i,s as A,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"良率、缺陷密度与芯片面积","description":"","frontmatter":{"title":"良率、缺陷密度与芯片面积","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/yield-defect-die-area.md","filePath":"litho/yield-defect-die-area.md","lastUpdated":1791063341000}'),d={name:"litho/yield-defect-die-area.md"};function D(h,a,_,m,c,f){const l=s("Mermaid");return t(),B("div",null,[a[2]||(a[2]=r('<h1 id="良率、缺陷密度与芯片面积" tabindex="-1">良率、缺陷密度与芯片面积 <a class="header-anchor" href="#良率、缺陷密度与芯片面积" aria-label="Permalink to &quot;良率、缺陷密度与芯片面积&quot;">​</a></h1><div class="epigraph"><p>随机缺陷使大芯片更难整片完好；缺陷密度与芯片面积把图形化质量接到成本上，而不仅接到某一层线宽。</p><footer>—— 据 Mack, Fundamental Principles of Optical Lithography 对缺陷限制良率的讨论整理</footer></div><p><a href="/litho/feol-beol-patterning">上一课</a>串起前道与后道的多层图形。本课是「器件与图形化的由来」最后一课。下一课 <a href="/litho/em-wave-index">单色波、折射率与光程</a> 进入成像与分辨率主线，从单色复振幅与光程重开，不再从器件结构起笔。缺口：为何图形缺陷如此昂贵？芯片面积如何进入良率？</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/contact-via-line">接触孔、通孔与线</a> 与 <a href="/litho/single-expose-limit">单次曝光极限</a> 说明图形又密又多层。即便图案在光学上「印出来了」，颗粒、桥连、断线仍会杀死整颗芯片。若没有良率 \\(Y\\) 与缺陷密度 \\(D_0\\) 的关系，无法理解为何缺陷是工厂核心指标，为何同样的 \\(D_0\\) 下大芯片比小芯片更怕。缺口是这张账，不是再排一层掩模。</p><h3 id="良率不是「平均线宽合格率」" tabindex="-1">良率不是「平均线宽合格率」 <a class="header-anchor" href="#良率不是「平均线宽合格率」" aria-label="Permalink to &quot;良率不是「平均线宽合格率」&quot;">​</a></h3><p>一层的临界尺寸均值合格，仍可能因稀疏缺陷或套刻尾部丢掉整颗。良率计的是「这颗芯片所有关键层都可用」，不是某一层的均值 CD。把光刻质量理解成「平均印得够细」，会低估大面积、多孔层的风险。</p><p><span class="marginnote">泊松模型的常用简化：\\(Y\\approx\\exp(-A D_0)\\)，\\(A\\) 为芯片面积，\\(D_0\\) 为单位面积致命缺陷数。聚集缺陷要用别的分布；本课用指数式建立面积敏感性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>良率 \\(Y\\)：好芯片数比上总芯片数。随机、独立缺陷近似泊松：期望缺陷数 \\(\\bar N=A D_0\\)，无缺陷概率 \\(e^{-\\bar N}\\)。\\(A\\) 加倍而 \\(D_0\\) 不变，\\(Y\\) 变成原来的平方（在指数模型里）。于是大芯片必须更低的 \\(D_0\\)，或接受更低 \\(Y\\)。降低 \\(D_0\\)：更洁净的环境、更稳的图形转移、检验与修补。</p><p>同一 \\(D_0\\) 下，小芯片可以「摊薄」缺陷：晶圆上同样密度的致命点，落在小颗上的期望更低。这是切芯片经济学与图形化质量的交点：不是大芯片光学更难，而是面积把同一图形化水平乘进指数。多层之后 \\(D_0\\) 近似各层致命贡献之和（独立时），所以后道层数多的产品更怕同一套工厂洁净度。</p><p><span class="marginnote">数字实例：取 \\(D_0=0.1\\)（每平方厘米 0.1 个致命缺陷）、\\(A=1\\) 平方厘米，期望缺陷 0.1 个，良率约 \\(e^{-0.1}\\approx 90\\%\\)；面积翻倍到 2 平方厘米，变成 \\(e^{-0.2}\\approx 82\\%\\)——缺陷一个没多，良率白白掉了约 8 个百分点。</span></p><p>图形化贡献：\\(D_0\\) 来自颗粒、桥连、断线、孔塞；尺寸与套刻的尾部把本来非致命的偏差变成致命。图形越密，同样物理尺寸的颗粒越容易致命。面积 \\(A\\) 则由功能与互连决定——器件课前半已经说明为何功能需要这么多层图形。</p><p><span class="marginnote">直觉类比：把芯片想成一篇长文，缺陷是随机落下的错字。错字率不变时，百字短文保持完好的机会远高于万字长文——大芯片不是更难「写」，而是暴露给随机错误的字数更多，指数式良率把这种暴露直接乘了出来。</span></p><p>聚集缺陷（同一来源的一簇）会让简单泊松偏乐观：簇内相关，有效致命数不再是 \\(A D_0\\) 的独立计数。本课不换模型，只提醒：指数式给出面积有多痛；真实工厂用的分布更肥尾。致命缺陷还与图形种类有关：能桥连两根最小间距线的颗粒，对稀疏大图形可能无害。因此 \\(D_0\\) 是「对这颗芯片的设计规则而言」的密度，不是空气里的颗粒计数本身。</p>',15)),(t(),o(n,null,{default:E(()=>[A(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20D0%5B%22%E7%BC%BA%E9%99%B7%E5%AF%86%E5%BA%A6%20D0%22%5D%20--%3E%20N%5B%22%E6%9C%9F%E6%9C%9B%E7%BC%BA%E9%99%B7%E6%95%B0%20A%20%E4%B9%98%20D0%22%5D%0A%20%20A%5B%22%E8%8A%AF%E7%89%87%E9%9D%A2%E7%A7%AF%20A%22%5D%20--%3E%20N%0A%20%20N%20--%3E%20Y%5B%22%E8%89%AF%E7%8E%87%E7%BA%A6%20exp(-N)%22%5D%0A%20%20PAT%5B%22%E5%A4%9A%E5%B1%82%E5%9B%BE%E5%BD%A2%E8%B4%A8%E9%87%8F%22%5D%20--%3E%20D0%0A%20%20Y%20--%3E%20COST%5B%22%E8%8A%AF%E7%89%87%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"经济学闭环：节距推进要求更严的缺陷预算；大芯片必须更干净或接受低良率。这解释了图形化投资为何与曝光工具并列——不只是为了把线印细，而是为了让足够大的面积在多层之后仍然完好。器件与图形化的由来在此收束：我们需要图形，因为晶体管与互连是画出来的；我们在乎图形质量，因为 \\(A\\) 与 \\(D_0\\) 直接乘进良率。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"致命比把「看见的缺陷」换成「能杀死芯片的缺陷」。同一颗粒落在宽金属上可能无害，落在最小节距上致命。\\(D_0\\) 必须带着设计规则一起读。")],-1)),(t(),o(n,null,{default:E(()=>[A(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E4%B8%80%E9%A2%97%E9%A2%97%E7%B2%92%E8%90%BD%E5%88%B0%E6%99%B6%E5%9C%86%22%5D%20--%3E%20WHERE%5B%22%E8%90%BD%E5%9C%A8%E5%93%AA%E7%B1%BB%E5%9B%BE%E5%BD%A2%E4%B8%8A%22%5D%0A%20%20WHERE%20--%3E%7C%22%E6%9C%80%E5%B0%8F%E8%8A%82%E8%B7%9D%E7%9A%84%E4%B8%A4%E6%A0%B9%E7%BA%BF%E4%B9%8B%E9%97%B4%22%7C%20LETH%5B%22%E6%A1%A5%E8%BF%9E%E6%88%96%E6%96%AD%E7%BA%BF%EF%BC%8C%E8%87%B4%E5%91%BD%22%5D%0A%20%20WHERE%20--%3E%7C%22%E5%AE%BD%E9%87%91%E5%B1%9E%E6%88%96%E5%88%92%E7%89%87%E6%A7%BD%22%7C%20OK%5B%22%E5%8F%AF%E8%83%BD%E6%97%A0%E5%AE%B3%22%5D%0A%20%20LETH%20--%3E%20DEAD%5B%22%E6%95%B4%E9%A2%97%E8%8A%AF%E7%89%87%E6%8A%A5%E5%BA%9F%EF%BC%8C%E8%AE%A1%E5%85%A5%20D0%22%5D%0A%20%20OK%20--%3E%20FINE%5B%22%E4%B8%8D%E5%BD%B1%E5%93%8D%E8%89%AF%E7%8E%87%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>下一课起，栏回到波动：单色场、折射率、光程。默认读者已经知道为何要持续缩小图形、为何缺陷与面积重要；不再从麦克斯韦或从临界尺寸口诀起笔，而是把成像符号一次钉死。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开致命比、缺陷分类机台与晶圆边缘排除。不把泊松模型当成唯一良率理论。成像主线的分辨公式不在本课推导。</p><p>晶圆边缘与标记区往往缺陷更高，有效 \\(A\\) 还要扣掉不能用的边。后课 <a href="/litho/em-wave-index">单色波、折射率与光程</a> 默认：图形化的对象与经济约束已经清楚；将从单色复振幅与光程开始讲成像。光学前置课与器件课都已读完。</p><p><span class="marginnote">初学者容易以为缺陷总是这里一个、那里一个地独立出现；实际上一颗迸溅的大颗粒会砸出一簇相邻缺陷，一次连坏一片相邻管芯。这就是「肥尾」的直觉：平均密度没变，坏芯片却成片出现，所以泊松公式在这种工厂偏乐观。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机缺陷下 \\(Y\\approx\\exp(-A D_0)\\)；芯片越大，\\(D_0\\) 越严。</li><li>图形化质量进入 \\(D_0\\)，不只进入平均线宽。</li><li>「器件与图形化的由来」在此结束：要图形，且要干净的大面积图形。</li><li>下一课进入成像主线，从单色波与光程开始。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',7))])}const x=p(d,[["render",D]]);export{C as __pageData,x as default};
